1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // A history request mutates nothing: it must not queue behind a streaming turn.
48	    if (isListSessionsFrame(rawMessage)) {
49	      return wsErrorHandler(ws, () => answerListSessions(ws, session, sessionStore, validation));
50	    }
51	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
52	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
53	  };
54	}
55	
56	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
57	async function answerInTurn(
58	  ws: WebSocket,
59	  session: ChatSession,
60	  orchestrator: ChatOrchestrator,
61	  validation: ValidationResult,
62	  signal: AbortSignal | undefined
63	): Promise<void> {
64	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
65	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
66	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
67	    return;
68	  }
69	  const startedAt = Date.now();
70	  try {
71	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
72	  } finally {
73	    endTurn(ws, session, signal, startedAt);
74	  }
75	}
76	
77	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
78	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
79	  if (signal?.aborted) {
80	    log.info('message', 'turn abandoned: its socket closed', {
81	      sessionId: session.sessionId,
82	      elapsedMs: Date.now() - startedAt,
83	    });
84	    return;
85	  }
86	  sendStreamEnd(ws);
87	}
88	
89	async function answerUserMessage(
90	  ws: WebSocket,
91	  session: ChatSession,
92	  orchestrator: ChatOrchestrator,
93	  validation: ValidationResult,
94	  signal: AbortSignal | undefined
95	): Promise<void> {
96	  const message = validation.valid ? validation.data : undefined;
97	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
98	  answerFrame(ws, validation);
99	}
100	
101	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
102	  if (!validation.valid) {
103	    log.warn('message', 'validation failed', {error: validation.error});
104	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
105	    return;
106	  }
107	
108	  const message = validation.data;
109	  if (message.type === 'ping') handlePing(ws, message.timestamp);
110	}
111	
112	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
113	function isUserMessageFrame(rawMessage: unknown): boolean {
114	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
115	}
116	
117	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
118	  try {
119	    await action();
120	  } catch (error) {
121	    const message = error instanceof Error ? error.message : 'Unknown error';
122	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
123	    log.error('message', 'handling error', {error: message, code});
124	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
125	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
126	      return;
127	    }
128	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
129	  }
130	}
131	
132	async function handleUserMessage(
133	  ws: WebSocket,
134	  session: ChatSession,
135	  orchestrator: ChatOrchestrator,
136	  content: string,
137	  signal: AbortSignal | undefined
138	): Promise<void> {
139	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
140	
141	  const userEntry = createUserEntry(content);
142	  const userIndex = appendEntry(session, userEntry);
143	  sendUpsert(ws, userIndex, userEntry);
144	
145	  const parser = new ThinkingTagParser();
146	  const state: StreamState = {
147	    thinkingIndex: null,
148	    assistantIndex: null,
149	    suppressOutput: false,
150	    sentAssistantIndices: [],
151	  };
152	
153	  let textChunkCount = 0;
154	
155	  try {
156	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
157	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
158	      if (signal?.aborted) break;
159	      textChunkCount = logChunk(chunk, textChunkCount);
160	      processChunk(ws, session, state, parser, chunk);
161	    }
162	  } finally {
163	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
164	    flushHeldText(ws, session, state, parser);
165	    closeCutOff(ws, session, state, 'thinkingIndex');
166	    closeCutOff(ws, session, state, 'assistantIndex');
167	  }
168	
169	  if (textChunkCount > 0) {
170	    log.debug('stream', `received ${textChunkCount} text chunks`);
171	  }
172	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
173	}
174	
175	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
176	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
177	  if (chunk.type === 'text') return textChunkCount + 1;
178	
179	  if (textChunkCount > 0) {
180	    log.debug('stream', `received ${textChunkCount} text chunks`);
181	  }
182	
183	  if (chunk.type === 'tool_result') {
184	    log.debug('stream', 'tool_result chunk', {
185	      messageCount: chunk.clientMessages.length,
186	      types: chunk.clientMessages.map(m => m.type),
187	    });
188	    return 0;
189	  }
190	
191	  log.debug('stream', 'chunk', {type: chunk.type});
192	  return 0;
193	}
194	
195	function processChunk(
196	  ws: WebSocket,
197	  session: ChatSession,
198	  state: StreamState,
199	  parser: ThinkingTagParser,
200	  chunk: MessageChunk
201	): void {
202	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
203	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
204	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
205	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
206	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
207	}
208	
209	function processTextChunk(
210	  ws: WebSocket,
211	  session: ChatSession,
212	  state: StreamState,
213	  parser: ThinkingTagParser,
214	  text: string
215	): void {
216	  const segments = parser.push(text);
217	  for (const segment of segments) {
218	    handleTextSegment(ws, session, state, segment);
219	  }
220	}
221	
222	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
223	  if (segment.type === 'thinking') {
224	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
225	    return;
226	  }
227	  commitAndClear(ws, session, state, 'thinkingIndex');
228	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
229	}
230	
231	function streamSegment(
232	  ws: WebSocket,
233	  session: ChatSession,
234	  state: StreamState,
235	  key: StateIndexKey,
236	  createEntry: EntryFactory,
237	  content: string
238	): void {
239	  const isNew = initSegment(session, state, key, createEntry);
240	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
241	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
242	  appendDelta(session, state[key]!, content);
243	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
244	}
245	
246	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
247	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
248	  markSuppressed(session, index);
249	  sendSkip(ws, index);
250	}
251	
252	function markSuppressed(session: ChatSession, index: number): void {
253	  const entry = session.entries[index];
254	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
255	}
256	
257	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
258	  if (state[key] !== null) return false;
259	  state[key] = appendEntry(session, createEntry());
260	  return true;
261	}
262	
263	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
264	  const index = state[key];
265	  if (index === null) return;
266	
267	  commitEntry(session, index);
268	  state[key] = null;
269	
270	  // Only what the client received can be retracted, and only assistant entries.
271	  if (state.suppressOutput) return;
272	
273	  sendCommit(ws, index);
274	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
275	}
276	
277	function processToolUseChunk(
278	  ws: WebSocket,
279	  session: ChatSession,
280	  toolCall: {name: string; input: Record<string, unknown>}
281	): void {
282	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
283	  const toolIndex = appendEntry(session, toolEntry);
284	  sendUpsert(ws, toolIndex, toolEntry);
285	}
286	
287	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
288	  for (const msg of clientMessages) {
289	    log.debug('stream', 'forwarding client message to frontend', {
290	      type: msg.type,
291	      index: 'index' in msg ? msg.index : undefined,
292	    });
293	    sendJson(ws, msg);
294	  }
295	}
296	
297	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
298	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
299	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
300	  commitOpenEntries(ws, session, state);
301	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
302	
303	  for (const idx of state.sentAssistantIndices) {
304	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
305	    markSuppressed(session, idx);
306	  }
307	
308	  state.sentAssistantIndices = [];
309	  state.suppressOutput = true;
310	}
311	
312	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
313	  flushHeldText(ws, session, state, parser);
314	  commitOpenEntries(ws, session, state);
315	}
316	
317	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
318	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
319	  for (const segment of parser.flush()) {
320	    handleTextSegment(ws, session, state, segment);
321	  }
322	}
323	
324	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
325	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
326	  const index = state[key];
327	  if (index === null) return;
328	  markTruncated(session, index);
329	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
330	  commitAndClear(ws, session, state, key);
331	}
332	
333	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
334	  commitAndClear(ws, session, state, 'thinkingIndex');
335	  commitAndClear(ws, session, state, 'assistantIndex');
336	}
337	
338	function handlePing(ws: WebSocket, timestamp: number): void {
339	  ws.send(JSON.stringify({type: 'pong', timestamp}));
340	}
341	
342	function isListSessionsFrame(rawMessage: unknown): boolean {
343	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_sessions';
344	}
345	
346	async function answerListSessions(
347	  ws: WebSocket,
348	  session: ChatSession,
349	  store: SessionStore | undefined,
350	  validation: ValidationResult
351	): Promise<void> {
352	  if (!validation.valid) {
353	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
354	    return;
355	  }
356	
357	  const message = validation.data;
358	  if (message.type !== 'list_sessions') return;
359	
360	  const {limit, before} = message;
361	
362	  if (!store?.listFor) {
363	    sendJson(ws, {type: 'session_list', sessions: []});
364	    return;
365	  }
366	
367	  try {
368	    const summaries = await store.listFor(session.userId, {limit, before});
369	    const sessions = summaries.map(s => ({
370	      sessionId: s.sessionId,
371	      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
372	      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
373	      entryCount: s.entryCount,
374	    }));
375	    sendJson(ws, {type: 'session_list', sessions});
376	  } catch (err) {
377	    const errorMsg = err instanceof Error ? err.message : String(err);
378	    log.error('ws', 'list sessions failed', {userId: session.userId, error: errorMsg});
379	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
380	  }
381	}
382

