1	// Local counterpart of the Lore spec-coverage job that consumes these links: a `([validated by](...))`
2	// link only counts when it sits in its statement's trailing parenthetical, so a
3	// link anywhere else is reported here rather than silently dropped there.
4	// Segmentation and link parsing come from the published spec domain
5	// of @re-cinq/eslint-plugin-re-lint (AGENTS.md § Spec Test Links).
6	
7	import { readFileSync, readdirSync } from "node:fs";
8	import { join, relative, resolve } from "node:path";
9	import process from "node:process";
10	import { findMisplacedCoverageLinks } from "@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js";
11	import { segmentStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-segment.js";
12	import { root } from "./lib/repo-root.mjs";
13	
14	const USAGE =
15	  "usage: check-spec-links.mjs [--json] [spec-path ...]\n" +
16	  "spec paths resolve against the repo root, not the working directory; an absolute path is taken as given";
17	
18	const args = process.argv.slice(2);
19	const flags = args.filter((arg) => arg.startsWith("--"));
20	const specArgs = args.filter((arg) => !arg.startsWith("--"));
21	
22	for (const flag of flags) {
23	  if (flag === "--json") {
24	    continue;
25	  }
26	  process.stderr.write(`${USAGE}\n`);
27	  process.exit(2);
28	}
29	
30	const asJson = flags.includes("--json");
31	
32	const discoverSpecs = () => {
33	  const specsDir = join(root, "specs");
34	  const slugs = readdirSync(specsDir, { withFileTypes: true })
35	    .filter((entry) => entry.isDirectory())
36	    .map((entry) => entry.name)
37	    .sort();
38	
39	  return [...slugs.map((slug) => `specs/${slug}/spec.md`), ".specify/spec.md"];
40	};
41	
42	const specPaths =
43	  specArgs.length > 0
44	    ? specArgs.map((path) => relative(root, resolve(root, path)))
45	    : discoverSpecs();
46	
47	const readSpec = (specPath) => {
48	  try {
49	    return readFileSync(join(root, specPath), "utf8");
50	  } catch (error) {
51	    process.stderr.write(`cannot read spec ${specPath}: ${error.message}\n`);
52	    process.exit(2);
53	  }
54	};
55	
56	const findings = [];
57	const specsWithFindings = new Set();
58	let statementsScanned = 0;
59	
60	for (const specPath of specPaths) {
61	  const content = readSpec(specPath);
62	
63	  for (const statement of segmentStatements(content)) {
64	    statementsScanned += 1;
65	
66	    for (const link of findMisplacedCoverageLinks(statement.text)) {
67	      findings.push({
68	        spec: specPath,
69	        line: statement.line ?? null,
70	        path: link.path,
71	        anchorLine: link.line,
72	        label: link.label,
73	        statement: statement.text,
74	      });
75	      specsWithFindings.add(specPath);
76	    }
77	  }
78	}
79	
80	const reportLines = () => {
81	  const lines = findings.map((finding) => {
82	    const anchor = finding.anchorLine === null ? "" : `#L${finding.anchorLine}`;
83	    const line = finding.line ?? "?";
84	
85	    return `${finding.spec}:${line}: ${finding.path}${anchor} cited outside the statement's trailing parenthetical`;
86	  });
87	
88	  lines.push(
89	    `misplaced: ${findings.length} across ${specsWithFindings.size} specs (${statementsScanned} statements scanned)`
90	  );
91	
92	  return lines;
93	};
94	
95	// process.exitCode, not process.exit: exiting truncates a large stdout write
96	// to a pipe.
97	process.exitCode = findings.length > 0 ? 1 : 0;
98	process.stdout.write(
99	  asJson ? `${JSON.stringify(findings, null, 2)}\n` : `${reportLines().join("\n")}\n`
100	);
101

