const asJson = flags.includes("--json");
const asCoverage = flags.includes("--coverage");

const markdownIn = (dir) =>
  readdirSync(join(root, dir), { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith(".md"))
