1	#!/usr/bin/env node
2	// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
3	//
4	// Usage:
5	//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
6	//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
7	//
8	// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
9	// it, and the citation silently lands on a different, still-valid declaration. The name is what the
10	// author meant, so the name is what the citation records and the line becomes a derived pointer this
11	// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
12	// citation without one marks the whole file covered rather than one test.
13	import {readFileSync, writeFileSync} from 'node:fs';
14	import {execFileSync} from 'node:child_process';
15	import process from 'node:process';
16	import {dirname, join, normalize} from 'node:path';
17	import {root} from './lib/repo-root.mjs';
18	
19	const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
20	// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
21	// to the same file and counts them, while this gate and the drift check would never have read them.
22	const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
23	// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
24	const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
25	const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
26	const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;
27	
28	const cache = new Map();
29	const args = process.argv.slice(2);
30	const fix = args.includes('--fix');
31	const named = args.filter(arg => !arg.startsWith('--'));
32	const findings = [];
33	let checked = 0;
34	let repaired = 0;
35	
36	for (const spec of named.length > 0 ? named : specs()) {
37	  const source = readFileSync(join(root, spec), 'utf8');
38	  const specDir = dirname(spec);
39	  let changed = false;
40	
41	  for (const match of source.matchAll(ANY_HREF)) {
42	    if (!match.groups.path.startsWith('../')) {
43	      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
44	    }
45	  }
46	
47	  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
48	    const groups = rest[rest.length - 1];
49	    const target = normalize(join(specDir, groups.path));
50	    if (!TEST_FILE.test(target)) return whole;
51	
52	    checked += 1;
53	    const declarations = declarationsIn(target);
54	    if (declarations === null) {
55	      findings.push(`${spec}: ${groups.path} does not exist`);
56	      return whole;
57	    }
58	
59	    const named = groups.label ? groups.label.slice(2) : null;
60	    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));
61	
62	    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
63	    if (skipped) {
64	      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
65	      return whole;
66	    }
67	
68	    if (named === null) {
69	      if (!atLine) {
70	        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
71	        return whole;
72	      }
73	      if (nameIsAmbiguous(declarations, atLine.name)) {
74	        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
75	        return whole;
76	      }
77	      if (!fix) {
78	        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
79	        return whole;
80	      }
81	      return rewrite(atLine.name, groups.path, atLine.line);
82	    }
83	
84	    // Checked before the line is consulted: a name that identifies two declarations is not an
85	    // identifier, and while the line happens to agree nothing would ever say so.
86	    if (nameIsAmbiguous(declarations, named)) {
87	      findings.push(ambiguity(spec, groups.path, named, declarations));
88	      return whole;
